// Optional, bounded image decoding for bundles already warmed by a scene
// roster. This never runs in the headless renderer and never fetches a URL
// that the ordinary render-side host gate would reject.

import { isHostAllowed } from "@lumencast/protocol";
import type { RenderBundle, RenderNode } from "./bundle";
import { readAllowedHosts } from "./allowed-hosts";

const MAX_NODES = 4096;
const MAX_IMAGES_PER_BUNDLE = 4;
const MAX_RETAINED_IMAGES = 12;
const MAX_RETAINED_PIXELS = 12_000_000;

export interface RosterImagePreloadResult {
  candidates: number;
  decoded: number;
  notReady: number;
}

/** Bundle-authored raster sources only. A bound `src` can have an authored
 * fallback that the first snapshot still uses; a later live value is never
 * guessed or fetched here. */
function imageSources(bundle: RenderBundle): string[] {
  const allowedHosts = readAllowedHosts(bundle);
  const found = new Set<string>();
  const stack: RenderNode[] = bundle.root && typeof bundle.root === "object" ? [bundle.root] : [];
  let visited = 0;

  const add = (value: unknown): void => {
    if (found.size >= MAX_IMAGES_PER_BUNDLE || typeof value !== "string") return;
    // Inline data images already have their bytes. The protocol gate below
    // retains the exact scheme + host policy used by the render path.
    if (!/^https:\/\//i.test(value) || !isHostAllowed(value, allowedHosts)) return;
    found.add(value);
  };

  while (stack.length > 0 && visited < MAX_NODES && found.size < MAX_IMAGES_PER_BUNDLE) {
    const node = stack.pop()!;
    visited += 1;
    if (!node || typeof node !== "object") continue;
    const props = node.props;
    if (props) {
      if (node.kind === "image") add(props.src);
      const fillKey =
        node.kind === "shape" ? "fills" : node.kind === "frame" ? "backgrounds" : null;
      if (fillKey && Array.isArray(props[fillKey])) {
        for (const fill of props[fillKey]) {
          if (fill && typeof fill === "object" && fill.kind === "image") add(fill.src);
        }
      }
      const mask = props.mask;
      if (mask && typeof mask === "object") {
        const typed = mask as {
          type?: unknown;
          op?: unknown;
          source?: { kind?: unknown; src?: unknown };
        };
        if (
          (typed.type === "alpha" || typed.type === "luminance") &&
          (typed.op === "intersect" || typed.op === "subtract" || typed.op === "union") &&
          typed.source?.kind === "image"
        ) {
          add(typed.source.src);
        }
      }
    }
    if (Array.isArray(node.children)) {
      for (let index = node.children.length - 1; index >= 0; index -= 1) {
        const child = node.children[index];
        if (child && typeof child === "object") stack.push(child);
      }
    }
  }
  return [...found];
}

/** A mount-local cache, so disconnect releases decoded image references.
 * Even when the roster is large, it starts at most 12 image loads and retains
 * no more than 12 MP of successful decodes. A switch never waits on it. */
export function createRosterImagePreloader(): {
  warm: (bundle: RenderBundle) => Promise<RosterImagePreloadResult>;
  clear: () => void;
} {
  const retained = new Map<string, HTMLImageElement>();
  const inFlight = new Map<string, Promise<boolean>>();
  let retainedPixels = 0;
  let active = true;

  async function decode(url: string): Promise<boolean> {
    if (retained.has(url)) return true;
    const existing = inFlight.get(url);
    if (existing) return existing;
    if (!active || retained.size + inFlight.size >= MAX_RETAINED_IMAGES) return false;

    const pending = (async () => {
      try {
        const image = new Image();
        image.decoding = "async";
        if (typeof image.decode === "function") {
          image.src = url;
          await image.decode();
        } else {
          await new Promise<void>((resolve, reject) => {
            image.onload = () => resolve();
            image.onerror = () => reject(new Error("image preload failed"));
            image.src = url;
          });
        }
        const pixels = image.naturalWidth * image.naturalHeight;
        if (
          !active ||
          !Number.isFinite(pixels) ||
          pixels <= 0 ||
          pixels + retainedPixels > MAX_RETAINED_PIXELS
        )
          return false;
        retained.set(url, image);
        retainedPixels += pixels;
        return true;
      } catch {
        // Best-effort only: the actual scene retains its normal image path.
        return false;
      }
    })();
    inFlight.set(url, pending);
    try {
      return await pending;
    } finally {
      inFlight.delete(url);
    }
  }

  return {
    async warm(bundle) {
      const urls = imageSources(bundle);
      const outcomes = await Promise.all(urls.map(decode));
      const decoded = outcomes.filter(Boolean).length;
      return { candidates: urls.length, decoded, notReady: urls.length - decoded };
    },
    clear() {
      active = false;
      retained.clear();
      inFlight.clear();
      retainedPixels = 0;
    },
  };
}
